"use strict";
window.runPanelInteractions = async ctx => {
    const { mount, current, plugin, load, settle, assert, input, files, contents, pages, metadataCache, index } = ctx;
    const actual = plugin.taskService, gates = [], originalQuery = actual.queryStructured.bind(actual);
    let delay = false, fail = false, queryCalls = 0;
    plugin.taskService = { subscribe: actual.subscribe.bind(actual), resolveLegacyAction: actual.resolveLegacyAction.bind(actual), resolveReveal: actual.resolveReveal.bind(actual),
        queryStructured: async options => { queryCalls++; if (fail) throw Error("Deterministic query failure");
            const value = await originalQuery(options); if (delay) await new Promise(resolve => gates.push(resolve)); return value; } };
    const waitGate = async () => { for (let i = 0; i < 200 && !gates.length; i++) await Promise.resolve(); assert(gates.length, "Delayed read started"); };
    const invalidate = async () => { plugin.taskData.invalidateAll(); await settle(); };
    const active = await mount(current, input.workspaces[0]), { root, panel } = active;
    const rowFor = text => [...root.querySelectorAll(".project-task-row")].find(row => row.querySelector(".project-task-text")?.textContent === text);
    let row = rowFor("Unscheduled"), checkbox = row.querySelector('input[type="checkbox"]');
    delay = true; await invalidate(); await waitGate(); ctx.setImportPaused(true);
    checkbox.checked = true; checkbox.dispatchEvent(new Event("change", { bubbles: true })); await settle();
    assert(panel.tasks.find(task => task.text === "Unscheduled").completed, "Immediate completion before old read resolves");
    gates.splice(0).forEach(resolve => resolve()); delay = false; await settle();
    assert(panel.tasks.find(task => task.text === "Unscheduled").completed, "Old query cannot revert completion");
    await panel.renderCurrentTasks(); await settle(); assert(panel.tasks.find(task => task.text === "Unscheduled").completed, "Lagging cached index cannot revert completion");
    const path = "Projects/App/Tasks/Unscheduled.md"; index(files.get(path)); metadataCache.emit("dataview:metadata-change", "update", files.get(path));
    ctx.setImportPaused(false); await settle();
    assert(ctx.facts().history.length === 1 && ctx.facts().oathChanges === 1, "Exactly one actual writer history event and Oath feedback");
    const completed = root.querySelector(".hub-task-group-toggle[aria-expanded='false']");
    const completedGroup = [...root.querySelectorAll(".hub-task-group-toggle")].find(button => button.textContent.includes("completed"));
    completedGroup.click(); await settle(); row = rowFor("Unscheduled"); checkbox = row.querySelector('input[type="checkbox"]');
    checkbox.checked = false; checkbox.dispatchEvent(new Event("change", { bubbles: true })); await settle();
    assert(!panel.tasks.find(task => task.text === "Unscheduled").completed, "Reopen uses existing checkbox writer");
    row = rowFor("Assignment\ncontinuation evidence"); row.querySelector(".hub-task-steps-toggle").click(); await settle();
    const step = row.querySelectorAll('.hub-task-step-item input')[1]; step.checked = true; step.dispatchEvent(new Event("change", { bubbles: true })); await settle();
    assert(contents.get("Projects/App/Tasks/Continuation.md").includes("[x] Next"), "Real Step checkbox writes source");
    assert(root.querySelector(".hub-task-steps-toggle[aria-expanded='true']"), "Step disclosure survives refresh");
    row = rowFor("Unscheduled"); const text = row.querySelector(".project-task-text");
    text.dispatchEvent(new KeyboardEvent("keydown", { key: "Enter", bubbles: true })); await settle();
    assert(window.lastModal?.modalEl.getAttribute("aria-label") === "Edit task", "Keyboard opens existing task editor");
    const modal = window.lastModal, title = modal.contentEl.querySelector("textarea"); title.focus(); title.value = "Pending task draft"; title.dispatchEvent(new Event("input", { bubbles: true }));
    await invalidate(); assert(title.isConnected && title.value === "Pending task draft" && document.activeElement === title, "Task draft and focus survive invalidation");
    modal.close();
    rowFor("Assignment\ncontinuation evidence").querySelector(".project-task-text").click(); await settle();
    const stepModal = window.lastModal;
    stepModal.contentEl.querySelector('[aria-label^="Edit Step:"]')?.click();
    const stepText = stepModal.contentEl.querySelector('textarea[aria-label="Step text"]');
    assert(stepText, "Existing Step textarea is present"); stepText.focus(); stepText.value = "Unsaved Step draft"; stepText.dispatchEvent(new Event("input", { bubbles: true }));
    await invalidate(); assert(stepText.isConnected && stepText.value === "Unsaved Step draft" && document.activeElement === stepText, "Step text draft and focus survive refresh");
    [...stepModal.contentEl.querySelectorAll("button")].find(button => button.textContent === "Add step").click();
    const pendingStep = stepModal.contentEl.querySelector('textarea[aria-label="New step"]');
    pendingStep.value = "Pending new Step"; pendingStep.focus(); pendingStep.dispatchEvent(new Event("input", { bubbles: true }));
    await invalidate(); assert(pendingStep.isConnected && pendingStep.value === "Pending new Step" && document.activeElement === pendingStep, "Pending Step creation survives refresh");
    stepModal.close();
    root.querySelector('[aria-label="Add task"]').click(); await settle();
    assert(window.lastModal.modalEl.getAttribute("aria-label") === "Add task", "Header Add opens unchanged creator"); window.lastModal.close();
    row = rowFor("Unscheduled"); row.dispatchEvent(new MouseEvent("contextmenu", { bubbles: true, clientX: 40, clientY: 40 })); await settle();
    assert(document.querySelector(".menu")?.textContent.includes("Add task above"), "Existing context menu actions retained");
    const menuBefore = document.querySelector(".menu"); await invalidate(); assert(menuBefore.isConnected, "Unchanged read retains menu and rows");
    document.dispatchEvent(new KeyboardEvent("keydown", { key: "Escape", bubbles: true }));
    // Exercise the actual inline Add state and existing defer mechanism.
    row.dispatchEvent(new MouseEvent("contextmenu", { bubbles: true, clientX: 40, clientY: 40 })); await settle();
    [...document.querySelectorAll(".menu button")].find(button => button.textContent === "Add task below").click(); await settle();
    const inline = root.querySelector(".hub-task-editor"); assert(inline, "Existing inline editor starts");
    inline.value = "Pending inline draft"; inline.focus(); await invalidate();
    assert(inline.isConnected && inline.value === "Pending inline draft" && document.activeElement === inline, "Inline draft/focus survives refresh");
    inline.dispatchEvent(new KeyboardEvent("keydown", { key: "Escape", bubbles: true })); await settle();
    fail = true; await invalidate(); assert(root.querySelector("[data-task-read-status]"), "Query-wide failure shows restrained status");
    assert(panel.tasks.length > 0 && root.querySelectorAll("[data-task-read-status]").length === 1, "Failure retains rows without notices");
    fail = false; await invalidate(); assert(!root.querySelector("[data-task-read-status]"), "Index recovery removes status");
    // Mode/rail changes invalidate publication even if the same panel survives.
    delay = true; await invalidate(); await waitGate(); active.env.taskWorkspace = { active: () => true };
    const before = root.innerHTML; gates.splice(0).forEach(resolve => resolve()); delay = false; await settle();
    assert(root.innerHTML === before, "Schedule/Roadmap/note rail prevents stale Work publication");
    active.env.taskWorkspace = null; await panel.renderCurrentTasks();
    row = rowFor("Unscheduled"); row.dispatchEvent(new MouseEvent("contextmenu", { bubbles: true, clientX: 40, clientY: 40 })); await settle();
    [...document.querySelectorAll(".menu button")].find(button => button.textContent === "Add task below").click(); await settle();
    const closingDraft = root.querySelector(".hub-task-editor"); closingDraft.value = "Saved while panel closes";
    active.component.unload(); root.remove();
    await settle(); assert([...contents.values()].some(text => text.includes("Saved while panel closes")), "Existing inline close/save survives read-session disposal");
    delay = true; const a = await mount(current, input.workspaces[0]); await waitGate(); a.component.unload(); a.root.remove();
    delay = false; const knowledge = await mount(current, input.workspaces.find(owner => owner.resourceType === "study"));
    gates.splice(0).forEach(resolve => resolve()); await settle();
    assert(knowledge.panel.tasks.every(task => task.path.startsWith("Resources/Knowledge/")), "Late Project A never overwrites Knowledge");
    knowledge.component.unload(); knowledge.root.remove();
    for (let i = 0; i < 10; i++) { const view = await mount(current, input.workspaces[i % input.workspaces.length]); view.component.unload(); view.root.remove(); }
    assert(plugin.taskData.subscribers.size === 0, "Repeated panel mounts release backend watcher");
    delay = true; const closing = await mount(current, input.workspaces[0]); await waitGate(); closing.component.unload(); closing.root.remove();
    await actual.close(); gates.splice(0).forEach(resolve => resolve()); await settle();
    assert(plugin.taskData.subscribers.size === 0 && ctx.notices.length === 0, "Plugin close during pending read is quiet and leak free");
    plugin.taskService = actual; window.panelInteractionEvidence = { queryCalls, historyEvents: ctx.facts().history.length };
};
